def sequential_search(arr: list, element: any) -> tuple:
    """
    Performs a sequential search on an array to find an element.

    Args:
        arr: The list to search through.
        element: The element to search for.

    Returns:
        A tuple (found, index) where found is a boolean and index is the
        position of the element (or -1 if not found).
    """
    for i in range(len(arr)):
        if arr[i] == element:
            return (True, i)
    return (False, -1)
```

