def dict_depth(d: dict) -> int:
    """Find the maximum nesting depth of a dictionary."""
    if not isinstance(d, dict):
        return 0
    return 1 + max((dict_depth(v) for v in d.values() if isinstance(v, dict)), default=0)
```

